//! `hg-ucd`: the Unicode Character Database as sorted tables.
//!
//! The tables are generated by `hg-unicode-build` from the pinned
//! database and checked in, so this crate builds with no network, no
//! build script and no Unicode files on disk; their freshness is a test
//! (G16). The derived tables are standards data and ship; the database
//! they come from does not.
//!
//! The algorithms over these tables are `hg-unicode`'s. This crate holds
//! data and the three lookups that know each table's shape.

pub mod generated;

pub use generated::tables::{
    BIDI, BidiClass, CANONICAL, CCC, COMPATIBILITY, COMPOSE, IDNA, IDNA_POOL, JOINING, JoiningType,
    MARKS, POOL, QUICK_CHECK, STATUS_NAMES, VERSION,
};

/// The canonical combining class of `c`, zero when it has none.
#[must_use]
pub fn combining_class(c: char) -> u8 {
    let cp = u32::from(c);
    CCC.binary_search_by_key(&cp, |(k, _)| *k)
        .ok()
        .and_then(|i| CCC.get(i))
        .map_or(0, |(_, v)| *v)
}

/// The fully expanded canonical decomposition of `c`, or `None` when it
/// has none.
#[must_use]
pub fn canonical(c: char) -> Option<&'static [char]> {
    slice(CANONICAL, POOL, c)
}

/// The fully expanded compatibility decomposition of `c`, or `None`.
/// Canonical mappings are included, as UAX #15 requires.
#[must_use]
pub fn compatibility(c: char) -> Option<&'static [char]> {
    slice(COMPATIBILITY, POOL, c)
}

/// The primary composite of `first` and `second`, or `None` when the pair
/// does not compose (UAX #15, Section 15).
#[must_use]
pub fn compose(first: char, second: char) -> Option<char> {
    let key = (u64::from(u32::from(first)) << 32) | u64::from(u32::from(second));
    let i = COMPOSE.binary_search_by_key(&key, |(k, _)| *k).ok()?;
    COMPOSE.get(i).and_then(|(_, v)| char::from_u32(*v))
}

/// The four quick-check values of `c`, packed two bits per form: NFC in
/// bits 0–1, then NFD, NFKC and NFKD. 0 is `Yes`, 1 `Maybe`, 2 `No`.
#[must_use]
pub fn quick_check(c: char) -> u8 {
    let cp = u32::from(c);
    match QUICK_CHECK.binary_search_by(|(first, last, _)| {
        if *last < cp {
            core::cmp::Ordering::Less
        } else if *first > cp {
            core::cmp::Ordering::Greater
        } else {
            core::cmp::Ordering::Equal
        }
    }) {
        Ok(i) => QUICK_CHECK.get(i).map_or(0, |(_, _, bits)| *bits),
        Err(_) => 0,
    }
}

fn slice(
    index: &'static [(u32, u32, u8)],
    pool: &'static [char],
    c: char,
) -> Option<&'static [char]> {
    let cp = u32::from(c);
    let i = index.binary_search_by_key(&cp, |(k, _, _)| *k).ok()?;
    let (_, off, len) = index.get(i)?;
    let start = usize::try_from(*off).ok()?;
    let end = start.checked_add(usize::from(*len))?;
    pool.get(start..end)
}

/// Finds `cp` in a table of inclusive ranges, returning its row.
fn in_ranges<T: Copy>(table: &'static [(u32, u32, T)], cp: u32) -> Option<T> {
    let i = table
        .binary_search_by(|(first, last, _)| {
            if *last < cp {
                core::cmp::Ordering::Less
            } else if *first > cp {
                core::cmp::Ordering::Greater
            } else {
                core::cmp::Ordering::Equal
            }
        })
        .ok()?;
    table.get(i).map(|(_, _, v)| *v)
}

/// Whether `c`'s `General_Category` is `Mn`, `Mc` or `Me`.
#[must_use]
pub fn is_mark(c: char) -> bool {
    let cp = u32::from(c);
    MARKS
        .binary_search_by(|(first, last)| {
            if *last < cp {
                core::cmp::Ordering::Less
            } else if *first > cp {
                core::cmp::Ordering::Greater
            } else {
                core::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// `c`'s `Bidi_Class`, as far as RFC 5893 distinguishes them.
#[must_use]
pub fn bidi_class(c: char) -> BidiClass {
    in_ranges(BIDI, u32::from(c)).unwrap_or(BidiClass::L)
}

/// `c`'s `Joining_Type`.
#[must_use]
pub fn joining_type(c: char) -> JoiningType {
    in_ranges(JOINING, u32::from(c)).unwrap_or(JoiningType::U)
}

/// UTS #46's status for `c`, and its mapping when it has one.
///
/// The status is the word [`STATUS_NAMES`] gives for it; the mapping is
/// empty for every status but `mapped` and `deviation`. A code point
/// the table does not list is `disallowed`, which is what the standard
/// says of anything unassigned.
#[must_use]
pub fn idna(c: char) -> (&'static str, &'static [char]) {
    let cp = u32::from(c);
    let found = IDNA.binary_search_by(|(first, last, _, _, _)| {
        if *last < cp {
            core::cmp::Ordering::Less
        } else if *first > cp {
            core::cmp::Ordering::Greater
        } else {
            core::cmp::Ordering::Equal
        }
    });
    let Some((_, _, status, off, len)) = found.ok().and_then(|i| IDNA.get(i)).copied() else {
        return ("disallowed", &[]);
    };
    // Bit 7 marks `disallowed_STD3_mapped`, which maps like `mapped`
    // but is disallowed when STD3 rules are on.
    let std3 = status & 0x80 != 0;
    let name = STATUS_NAMES
        .get(usize::from(status & 0x7F))
        .copied()
        .unwrap_or("disallowed");
    let mapping = usize::try_from(off)
        .ok()
        .and_then(|o| IDNA_POOL.get(o..o.saturating_add(usize::from(len))))
        .unwrap_or(&[]);
    if std3 {
        return ("disallowed_STD3_mapped", mapping);
    }
    (name, mapping)
}
